#!/bin/bash
# Generated by `zfa package create-plugin`.
# Dev setup for this repo needs no path<->versioned conversion: the adapters
# commit a `pubspec_overrides.yaml` wiring the in-family packages to their
# `packages/` siblings, so a clean checkout builds against THIS tree rather
# than the last published release (arrrrny/zuraffa_inappwebview#7 review).
# pub does not put that file in the archive, so publishing still ships the
# hosted caret constraints declared in each `pubspec.yaml` — there is nothing
# to convert back after a publish either.
set -u
REPO_ROOT="$(cd "$(dirname "$0")/.." >/dev/null 2>&1; pwd -P)"
missing=0
for pkg in zuraffa_inappwebview_android zuraffa_inappwebview_ios zuraffa_inappwebview_macos; do
    [ -f "$REPO_ROOT/packages/$pkg/pubspec_overrides.yaml" ] || {
        echo "MISSING packages/$pkg/pubspec_overrides.yaml — a clean checkout of $pkg will not compile"
        missing=1
    }
done
[ "$missing" -eq 0 ] || exit 1
echo "Nothing to restore: the sibling overrides are committed and never published."
echo "Local sibling overrides (dependency_overrides) are dev-only and stay out of the archive."
